def purity(T,K):
    tot=0
    for k in np.unique(K):
        tot+=np.bincount(T[K==k],minlength=16).max()
    return tot/T.size
rng=np.random.default_rng(0)
for s in range(4):
    T=fwd(P,s).argmax(1).reshape(32,32)
    out=[]
    for m in range(1,33):
        for n in range(1,33):
            cells=m*n
            if cells>256 or cells<2:continue
            K=(A%m)*n+(B%n)
            pu=purity(T,K)
            perm=rng.permutation(T.ravel()).reshape(32,32)
            out.append((round(pu-purity(perm,K),3),m,n,round(pu,3)))
    out.sort(reverse=True);print("mod",s,out[:6])
    # thresholds / quantization
    out=[]
    for m in (1,2,4,8,16,32):
        for n in (1,2,4,8,16,32):
            if m*n in(1,) or m*n>256:continue
            K=(A//(32//m))*n+(B//(32//n))
            pu=purity(T,K);perm=rng.permutation(T.ravel()).reshape(32,32)
            out.append((round(pu-purity(perm,K),3),m,n,round(pu,3)))
    out.sort(reverse=True);print("quant",s,out[:4])
    for nm,K in (("a<b",(A<B)*1),("a==b",(A==B)*1),("a+b%2",(A+B)%2),("a%2",A%2),("b%2",B%2)):
        print(" ",nm,round(purity(T,K),3),end="")
